function demoFieldContent(field,i){let r=PAGE.rows[0]||{},d=DEMO_FIELD_DETAILS[PAGE.id]||{};if(d[field])return d[field];let base=BIZPAGE?.guidelines?.[i % (BIZPAGE.guidelines.length||1)]||['业务核查','核对所有输入、版本和授权审批'];let values=PAGE.columns.slice(0,8).map(c=>`${c.label}: ${r[c.key]??'待接入'}`).join('；');return `【合成演示 · ${PAGE.title} / ${field}】\n单据业务：${base[0]}。具体核查要求：${base[1]}。\n当前演示源记录：${values}。\n该字段须与原件及有效版本核对；没有原文或权限证据时不得判定为正式通过。`}
function renderFieldReader(){let el=document.getElementById('biz-field-reader');if(!el||!BIZPAGE)return;let checks=bizSaved('checks',{}),ids=BIZPAGE.fields.map((f,i)=>i).filter(i=>checks[i]===true||(checks[i]===undefined&&i<2)),d=BIZSTATE.docs.current;el.innerHTML=`<div class="fieldReaderHead"><strong>字段原文阅读器</strong><span class="tag">已选择 ${ids.length} / ${BIZPAGE.fields.length} 项</span></div><p class="muted">勾选左侧字段后，这里显示该字段的完整文本。优先使用当前已导入文件的原始匹配段落；未导入或未识别时展示明显标记的示例文字。</p>${ids.length?ids.map(i=>{let f=BIZPAGE.fields[i],match=d?.fields?.find(x=>x.i===i),ok=!!match?.value;return `<article class="fieldReaderItem"><header><b>${bizEsc(f)}</b><span class="tag ${ok?'good':'warn'}">${ok?'已提取原文 · 待人工复核':'DEMO 示范文本'}</span></header><div class="readText">${bizEsc(ok?match.value:demoFieldContent(f,i))}</div><small>来源：${bizEsc(ok?d.name+' / '+match.location:'合成演示业务模板；不代表真实上传或已批准')}</small></article>`}).join(''):'<div class="emptyReader">请勾选左侧字段，完整文本会立即显示在这里。</div>'}`;}
function inlineDiff(a,b,side){a=String(a||'');b=String(b||'');if(a===b)return bizEsc(side==='old'?a:b);let p=0;while(p<Math.min(a.length,b.length)&&a[p]===b[p])p++;let s=0;while(s<Math.min(a.length-p,b.length-p)&&a[a.length-1-s]===b[b.length-1-s])s++;let cur=side==='old'?a:b;let mid=cur.slice(p,cur.length-s);return bizEsc(cur.slice(0,p))+`<mark class="${side==='old'?'diffDelete':'diffAdd'}">${bizEsc(mid||'∅')}</mark>`+bizEsc(s?cur.slice(cur.length-s):'');}
function locateDocLine(d,label){
 if(!d?.text||!label)return -1;
 const lines=d.text.split(/\r?\n/),exact='【'+label+'】';
 let at=lines.findIndex(x=>x.trim().startsWith(exact)||x.trim().startsWith(label+'：')||x.trim().startsWith(label+':'));
 if(at>=0)return at;
 const field=d.fields?.find(x=>x.label===label&&x.value&&x.location&&/\d+/.test(x.location));
 if(field){const n=Number(field.location.match(/(\d+)\s*$/)?.[1]);if(n>0&&n<=lines.length)return n-1;}
 return -1;
}
function focusDocFilter(){
 const box=document.getElementById('biz-doc-section');if(!box)return;
 let label=BIZSTATE.docLocate===''?null:BIZPAGE?.fields[Number(BIZSTATE.docLocate)];
 if(label&&box.tagName==='DETAILS')box.open=true;
 refreshVersionReaders();
 const states=[];
 ['current','old'].forEach(slot=>{let reader=document.getElementById('biz-reader-'+slot),target=reader?.querySelector('.docSelected'),d=BIZSTATE.docs[slot];
 if(!label){states.push(slot==='current'?'新版：展示全文':'旧版：展示全文');return;}
 if(target){reader.scrollTop+=target.getBoundingClientRect().top-reader.getBoundingClientRect().top-54;states.push((slot==='current'?'新版':'旧版')+'：已定位到相应段落');}
 else states.push((slot==='current'?'新版':'旧版')+(d?.text?'：未识别相应字段，需人工查找':'：尚无可定位文本'));
 });
 const status=document.getElementById('biz-locate-status');if(status)status.textContent=states.join('；');
}
function docPreview(d,side){if(!d)return '<div class="emptyReader">未选择文件。可以点击上方“载入版本差异示例”立即体验。</div>';let other=BIZSTATE.docs[side==='old'?'current':'old'];if(d.text){let lines=d.text.split(/\r?\n/);let ol=(other?.text||'').split(/\r?\n/);let selectedLabel=BIZSTATE.docLocate===''?null:BIZPAGE?.fields[Number(BIZSTATE.docLocate)],selectedLine=locateDocLine(d,selectedLabel);return `<div class="docExcerpt">${lines.map((l,i)=>{let different=other&&l!==ol[i];let inner=different?detailedCharDiff(side==='old'?l:ol[i]||'',side==='old'?ol[i]||'':l,side):bizEsc(l);return `<div class="docLine ${different?'changedLine':''} ${i===selectedLine?'docSelected':''}" data-doc-line="${i}"><span class="lineNo">${i+1}</span><span>${inner||'&nbsp;'}</span></div>`}).join('')}</div>`;}if(d.url&&d.type==='pdf')return `<iframe class="binaryPreview" title="PDF 原始文件预览" src="${d.url}"></iframe><p class="muted">PDF 可以直接阅读原件；无可核验文本抽取时不能提供逐字差异高亮。请接入带页码定位的 PDF/OCR 服务。</p>`;if(d.url&&['jpg','jpeg','png','webp'].includes(d.type))return `<img class="binaryImage" src="${d.url}" alt="上传的原始图片"><p class="muted">图片可以直接阅读；文字差异需可信 OCR 服务，当前未提取或伪造。</p>`;return `<div class="emptyReader">${bizEsc(d.parser)}。已保存文件名和版本位置；此类型需后端解析才能显示结构化差异。</div>`;}
function refreshVersionReaders(){for(let slot of ['current','old']){let el=document.getElementById('biz-reader-'+slot),d=BIZSTATE.docs[slot];if(!el)continue;el.innerHTML=`<div class="versionMeta"><b>${bizEsc(d?.name||'尚未上传')}</b><span class="tag">${bizEsc(d?.parser||'等待上传')}</span></div>${docPreview(d,slot)}`;}}
