const fmt=(v,mode,unit='')=>{if(v===null||v===undefined||!Number.isFinite(Number(v)))return '—';const n=Number(v);if(mode==='percent')return (n*100).toFixed(1)+'%';if(mode==='money'||unit==='USD')return n.toLocaleString('en-US',{maximumFractionDigits:2})+(unit==='USD'?' USD':'');if(unit==='天')return n.toLocaleString('zh-CN',{maximumFractionDigits:1})+' 天';return n.toLocaleString('zh-CN',{maximumFractionDigits:1})+(unit&&unit!=='%'?' '+unit:'');};
// V2948: no missing numeric value may be coerced to zero; empty/zero denominators block results.
const calculate=(m,rows)=>{if(!m||!rows.length)return null;if(window.__PE_SITE_SYNC&&!window.__PE_SITE_SYNC.allowed_metrics.includes(m.key))return null;
 const valid=r=>r!==undefined&&r!==null&&r!==''&&Number.isFinite(Number(r));
 const sum=f=>rows.every(r=>valid(r[f]))?rows.reduce((a,r)=>a+Number(r[f]),0):null;
 if(m.op==='count')return rows.length;
 const num=sum(m.field);if(num===null)return null;
 if(m.op==='sum')return num;
 if(m.op==='avg'||m.op==='rate')return num/rows.length;
 if(m.op==='ratio'){const den=sum(m.denom_field);return den===null||den===0?null:num/den;}
 if(m.op==='sumif')return rows.every(r=>r[m.condition_field]!==undefined&&r[m.condition_field]!==null&&r[m.condition_field]!=='' )?rows.filter(r=>r[m.condition_field]===m.condition_value).reduce((a,r)=>a+Number(r[m.field]),0):null;
 return null;};
